<h1 class="h3 mb-3">购买子域名</h1><div class="card"><div class="card-body"><p>根域名：<b class="mono"><?= h($domain['domain']) ?></b></p><p>价格：<?= money($domain['price']) ?> / <?= h($domain['period_days']) ?> 天；前缀长度 <?= h($domain['min_len']) ?>-<?= h($domain['max_len']) ?></p><?php if ($availableCount !== -1): ?><p class="small <?= $availableCount ? 'text-muted' : 'text-danger' ?>"><?= $availableCount ? '剩余 ' . (int)$availableCount : '已售罄' ?></p><?php endif; ?><form method="post" data-coupon-form data-coupon-type="dns_sub_new" data-coupon-url="<?= h(url_to('index/order/coupon_preview')) ?>"><?= csrf_field() ?><input type="hidden" name="domain_id" value="<?= (int)$domain['id'] ?>"><div class="input-group mb-3"><input class="form-control" name="prefix" required><span class="input-group-text">.<?= h($domain['domain']) ?></span></div><?php include __DIR__ . '/../_coupon.php'; ?><button class="btn btn-primary" <?= $availableCount === 0 ? 'disabled' : '' ?>><?= $availableCount === 0 ? '已售罄' : '生成订单并支付' ?></button></form></div></div>
